    if (!(num(doc.amount) > 0)) return 'Amount must be more than 0.';
    if (!doc.account) return 'Choose the account.';
    if (doc.type === 'Transfer' && (!doc.to || doc.to === doc.account)) return 'A transfer needs two different accounts.';
